import React, { useState } from 'react';

const QuanLyThongBao = () => {
    // Quản lý việc nhấn nút "Mọi người" hoặc "Gửi riêng"
    const [tabActive, setTabActive] = useState('all'); // 'all' hoặc 'private'

    return (
        <div style={{...styles.mainContainer, backgroundImage: "url('../assets/nen_khung_chat.jpg')"}} className="glass-card">

            {/* PHẦN ĐẦU: Nút chọn Tab */}
            <div style={styles.headerTabs}>
                <button 
                    onClick={() => setTabActive('all')}
                    style={{...styles.tabBtn, backgroundColor: tabActive === 'all' ? '#333' : 'transparent', color: tabActive === 'all' ? '#fff' : '#333'}}
                >
                    Mọi người
                </button>
                <button 
                    onClick={() => setTabActive('private')}
                    style={{...styles.tabBtn, backgroundColor: tabActive === 'private' ? '#8b5e5e' : 'transparent', color: tabActive === 'private' ? '#fff' : '#333'}}
                >
                    Gửi riêng
                </button>
            </div>

            {/* PHẦN THÂN: Hiển thị thay đổi theo Tab */}
            <div style={styles.contentBody}>
                {tabActive === 'all' ? (
                    /* Giao diện Ảnh 2: Khung chat chung */
                    <div style={styles.fullChatView} className="fade-in">
                        <div style={styles.chatHistory}>
                            <div style={styles.msgLeft}>
                                <div style={styles.avatar}>101</div>
                                <div style={styles.bubble}>Hôm nay có lịch cắt điện không ạ?</div>
                            </div>
                        </div>
                        <div style={styles.inputRow}>
                            <input style={styles.input} placeholder="Nhập thông báo chung cho mọi người..." />
                            <button style={styles.sendBtn}>Gửi</button>
                        </div>
                    </div>
                ) : (
                    /* Giao diện Ảnh 3: Gửi riêng */
                    <div style={styles.privateView} className="fade-in">
                        {/* Cột trái: Chọn cư dân (Số phòng) */}
                        <div style={styles.roomSidebar}>
                            <p style={styles.sidebarTitle}>Chọn phòng nhận:</p>
                            <div style={styles.roomGrid}>
                                {[101, 102, 103, 104, 201, 202, 203, 204, 301, 302].map(room => (
                                    <div key={room} className="room-item">{room}</div>
                                ))}
                            </div>
                        </div>
                        {/* Cột phải: Khung chat riêng */}
                        <div style={styles.privateChatArea}>
                            <div style={styles.chatHistory}>
                                <p style={{textAlign: 'center', color: '#666', fontSize: '13px'}}>Đang soạn thông báo riêng cho phòng...</p>
                            </div>
                            <div style={styles.inputRow}>
                                <input style={styles.input} placeholder="Nhập nội dung thông báo riêng..." />
                                <button style={{...styles.sendBtn, backgroundColor: '#8b5e5e'}}>Gửi riêng</button>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

const styles = {
    mainContainer: { flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', overflow: 'hidden', backgroundSize: 'cover', backgroundPosition: 'center' },
    headerTabs: { padding: '20px', display: 'flex', gap: '15px', borderBottom: '1px solid rgba(255,255,255,0.2)' },
    tabBtn: { padding: '10px 25px', borderRadius: '20px', border: 'none', fontWeight: 'bold', cursor: 'pointer', transition: '0.3s' },
    contentBody: { flex: 1, display: 'flex', padding: '20px', overflow: 'hidden' },

    // Style cho chat chung
    fullChatView: { flex: 1, display: 'flex', flexDirection: 'column' },

    // Style cho chat riêng
    privateView: { flex: 1, display: 'flex', gap: '20px' },
    roomSidebar: { width: '220px', backgroundColor: 'rgba(255,255,255,0.5)', borderRadius: '20px', padding: '15px', display: 'flex', flexDirection: 'column' },
    sidebarTitle: { margin: '0 0 10px 0', fontSize: '13px', fontWeight: 'bold' },
    roomGrid: { display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '8px', overflowY: 'auto' },
    privateChatArea: { flex: 1, display: 'flex', flexDirection: 'column' },

    // Các thành phần nhỏ
    chatHistory: { flex: 1, padding: '10px' },
    msgLeft: { display: 'flex', gap: '10px', alignItems: 'center' },
    avatar: { width: '35px', height: '35px', borderRadius: '50%', backgroundColor: '#333', color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '10px', fontWeight: 'bold' },
    bubble: { backgroundColor: '#fff', padding: '12px 18px', borderRadius: '18px 18px 18px 0', fontSize: '13px', boxShadow: '0 2px 5px rgba(0,0,0,0.1)' },
    inputRow: { display: 'flex', gap: '10px', marginTop: '10px' },
    input: { flex: 1, padding: '15px', borderRadius: '15px', border: 'none', backgroundColor: 'rgba(255,255,255,0.9)', outline: 'none' },
    sendBtn: { padding: '0 30px', borderRadius: '15px', border: 'none', backgroundColor: '#333', color: '#fff', fontWeight: 'bold', cursor: 'pointer' }
};

export default QuanLyThongBao;
